const config = {
  "previewFeatures": [],
  "clientVersion": "7.10.0",
  "engineVersion": "0edf323efd1d98336f3f0a68684b56f689b900d3",
  "activeProvider": "sqlite",
  "inlineSchema": "// Terrifit — waitlist + demand-measurement schema.\n//\n// Dev runs on SQLite so the site boots with zero infrastructure.\n// Production: change provider to \"postgresql\" and point DATABASE_URL at it.\n// Array-shaped fields are stored as JSON strings so the schema is portable\n// between both providers without a migration rewrite.\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"sqlite\"\n}\n\nmodel WaitlistEntry {\n  id    String @id @default(cuid())\n  email String @unique\n\n  name String\n  // athlete | coach | nutritionist | creator | brand\n  role String\n\n  // Market + demand signal\n  country  String\n  locale   String @default(\"en\")\n  // JSON string[] — which parts of the product they actually want\n  features String @default(\"[]\")\n\n  // Professional applicants (coach / nutritionist / creator)\n  handle       String?\n  audienceSize String?\n  credentials  String?\n\n  // Brand applicants\n  brandName     String?\n  brandWebsite  String?\n  brandCategory String?\n\n  // Referral mechanics\n  referralCode   String  @unique\n  referredByCode String?\n  referrals      Int     @default(0)\n\n  // Raw signup order. Displayed position subtracts the referral boost.\n  position Int\n\n  source    String?\n  createdAt DateTime @default(now())\n\n  @@index([role])\n  @@index([referredByCode])\n  @@index([country])\n}\n\n// Event-based analytics from day one, per the technical direction.\nmodel AnalyticsEvent {\n  id        String   @id @default(cuid())\n  name      String\n  sessionId String\n  locale    String?\n  path      String?\n  // JSON object of event properties\n  props     String   @default(\"{}\")\n  createdAt DateTime @default(now())\n\n  @@index([name])\n  @@index([sessionId])\n  @@index([createdAt])\n}\n\n// Messages from the contact page. Stored rather than only emailed so nothing is\n// lost if mail delivery fails, and so the team can see what is unanswered.\nmodel ContactMessage {\n  id String @id @default(cuid())\n\n  // member | band | creator | partner | press | other\n  topic   String\n  name    String\n  email   String\n  message String\n\n  locale     String  @default(\"en\")\n  // Set when the sender is already on the waitlist, so replies have context.\n  waitlistId String?\n\n  handled   Boolean  @default(false)\n  createdAt DateTime @default(now())\n\n  @@index([topic])\n  @@index([createdAt])\n  @@index([email])\n}\n\n// Storefront orders. Money is stored in integer minor units throughout — a\n// float total is a rounding bug waiting to reach a customer's card.\nmodel Order {\n  id String @id @default(cuid())\n\n  // Short human-quotable reference, e.g. TF-7K4M2P.\n  number String @unique\n\n  email String\n  name  String\n  phone String?\n\n  // Shipping address. Null for an order with nothing physical in it.\n  line1    String?\n  line2    String?\n  city     String?\n  postcode String?\n  country  String?\n\n  currency      String @default(\"USD\")\n  subtotalCents Int\n  shippingCents Int    @default(0)\n  taxCents      Int    @default(0)\n  totalCents    Int\n\n  // card | paypal | crypto | invoice\n  paymentMethod String\n  // pending | paid | failed | refunded\n  paymentStatus String  @default(\"pending\")\n  // The gateway's identifier for the charge, once one exists.\n  paymentRef    String?\n  // Set when the order went through a gateway running in sandbox mode.\n  sandbox       Boolean @default(false)\n\n  // pending | fulfilled | cancelled\n  fulfillmentStatus String @default(\"pending\")\n\n  locale String      @default(\"en\")\n  items  OrderItem[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([email])\n  @@index([paymentStatus])\n  @@index([createdAt])\n}\n\n/// A customer's review of something they bought.\n///\n/// Verified against their own orders at write time — `verified` is set when the\n/// account has a paid order containing that slug, and there is no way to set it\n/// from the request. The catalogue carries an aggregate rating for launch; once\n/// real reviews exist for a product, the aggregate shown is computed from these\n/// rows instead, so the number on the page is always one somebody can read.\nmodel ProductReview {\n  id   String @id @default(cuid())\n  slug String\n\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  /// 1–5 whole stars. Enforced in the API; SQLite has no check constraint here.\n  rating Int\n  title  String\n  body   String\n\n  /// True when the reviewer's account has a paid order containing this slug.\n  verified Boolean @default(false)\n  /// Hidden reviews stay in the table so moderation is reversible and auditable.\n  hidden   Boolean @default(false)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  /// One review per person per product. A rewrite updates the row.\n  @@unique([slug, userId])\n  @@index([slug, createdAt])\n}\n\nmodel OrderItem {\n  id      String @id @default(cuid())\n  orderId String\n  order   Order  @relation(fields: [orderId], references: [id], onDelete: Cascade)\n\n  slug      String\n  variantId String?\n  // Denormalised so an order still reads correctly after the catalogue changes.\n  title     String\n  variant   String?\n  unitCents Int\n  quantity  Int\n  subscribe Boolean @default(false)\n\n  @@index([orderId])\n}\n\n// ---------------------------------------------------------------------------\n// Accounts.\n//\n// Sessions are opaque random tokens stored as a SHA-256 hash, so a database\n// leak does not hand anybody a working session. Passwords use scrypt from the\n// Node standard library — no extra dependency, and correct by default.\n// ---------------------------------------------------------------------------\n\nmodel User {\n  id           String  @id @default(cuid())\n  email        String  @unique\n  passwordHash String\n  name         String\n  // Public handle, once they pick one. Optional so signup stays two fields.\n  handle       String? @unique\n\n  locale               String    @default(\"en\")\n  /// free | trial | pro — trial is a full-access Pro period that expires.\n  plan                 String    @default(\"free\")\n  planRenewsAt         DateTime?\n  /// When a free trial ends. Access is granted while this is in the future.\n  trialEndsAt          DateTime?\n  /// monthly | yearly, once they actually pay.\n  planInterval         String?\n  /// Set when someone has been offered the trial, so it is offered once.\n  trialStartedAt       DateTime?\n  /// Stripe's ids for this member. The subscription is the source of truth for\n  /// whether they are Pro; `plan` is a cache of it that the webhook writes.\n  /// Indexed rather than unique so adding the column needs no destructive\n  /// migration; one subscription per member is enforced where it is created.\n  stripeCustomerId     String?\n  stripeSubscriptionId String?\n  emailVerified        DateTime?\n  // athlete | creator | coach | partner\n  role                 String    @default(\"athlete\")\n  /// Separate from `role`, which is what someone *is* on the platform. Staff\n  /// access is an authorisation concern and must not be grantable by picking a\n  /// role at signup.\n  isAdmin              Boolean   @default(false)\n\n  profile     Profile?\n  sessions    Session[]\n  scans       BodyScan[]\n  connections HealthConnection[]\n  imports     HealthImport[]\n  metrics     HealthMetric[]\n\n  posts          Post[]\n  likes          PostLike[]\n  comments       Comment[]\n  devices        PushDevice[]\n  auditEntries   AuditLog[]\n  sentMessages   Message[]       @relation(\"sender\")\n  memberships    Conversation[]  @relation(\"members\")\n  bands          BandDevice[]\n  notifications  Notification[]\n  enrollments    MapEnrollment[]\n  reviews        ProductReview[]\n  passwordResets PasswordReset[]\n  sessionLogs    SessionLog[]\n  following      Follow[]        @relation(\"follower\")\n  followers      Follow[]        @relation(\"followee\")\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([createdAt])\n  @@index([stripeSubscriptionId])\n  @@index([stripeCustomerId])\n}\n\n/// A one-time link that lets somebody set a new password.\n///\n/// The token is stored as a SHA-256 hash for the same reason session tokens\n/// are: a leaked database must not hand anybody a working reset link. Rows are\n/// single-use and short-lived, and requesting a new one invalidates the old.\nmodel PasswordReset {\n  id String @id @default(cuid())\n\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  /// SHA-256 of the token in the emailed link. The plaintext exists only in\n  /// that email.\n  tokenHash String @unique\n\n  expiresAt DateTime\n  usedAt    DateTime?\n  createdAt DateTime  @default(now())\n\n  @@index([userId])\n  @@index([expiresAt])\n}\n\nmodel Session {\n  id String @id @default(cuid())\n\n  // SHA-256 of the cookie value. The plaintext token only ever exists in the\n  // browser's cookie jar and in the response that set it.\n  tokenHash String @unique\n\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  userAgent String?\n  ip        String?\n\n  expiresAt DateTime\n  createdAt DateTime @default(now())\n\n  @@index([userId])\n  @@index([expiresAt])\n}\n\nmodel Profile {\n  userId String @id\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  dateOfBirth DateTime?\n  // female | male | other | undisclosed — used only for metric baselines.\n  sex         String?\n  heightCm    Float?\n  weightKg    Float?\n  // metric | imperial. Display only; everything is stored in SI.\n  units       String    @default(\"metric\")\n  timezone    String?\n\n  // strength | fat-loss | endurance | health | recomposition\n  goal          String?\n  // sedentary | light | moderate | high | athlete\n  activityLevel String?\n  trainingDays  Int?\n\n  bio String?\n\n  /// Years training: new | returning | steady | advanced.\n  experience       String?\n  /// JSON array of what they actually do — \"lifting\", \"running\", \"cycling\"…\n  activities       String?\n  /// JSON array of anything a programme should work around. Free text allowed.\n  healthConditions String?\n  /// Set the moment onboarding is finished, so the app knows to stop asking.\n  onboardedAt      DateTime?\n\n  // Health metrics are private by default; this is the master switch a member\n  // flips before any per-creator sharing can apply.\n  shareWithCreators Boolean @default(false)\n\n  updatedAt DateTime @updatedAt\n}\n\n/// A body-composition measurement. InBody is the common case; DEXA, calipers\n/// and smart scales land in the same shape so the history stays comparable.\nmodel BodyScan {\n  id     String @id @default(cuid())\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  // inbody | dexa | scale | manual\n  source  String\n  takenAt DateTime\n\n  weightKg           Float?\n  bodyFatPercent     Float?\n  skeletalMuscleKg   Float?\n  leanMassKg         Float?\n  bodyWaterL         Float?\n  visceralFatLevel   Float?\n  basalMetabolicRate Int?\n  /// InBody's own 0–100 composite, when the sheet carries it.\n  score              Int?\n\n  /// The original row, kept so a parsing improvement can be replayed.\n  raw String?\n\n  createdAt DateTime @default(now())\n\n  @@index([userId, takenAt])\n}\n\n/// A link to another health app. Kept even when revoked, so the member can see\n/// what was once connected and when it stopped.\nmodel HealthConnection {\n  id     String @id @default(cuid())\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  // apple_health | google_health_connect | samsung_health | garmin | strava |\n  // fitbit | oura | whoop | inbody\n  provider String\n  // connected | pending | revoked\n  status   String @default(\"pending\")\n\n  externalId String?\n  scopes     String  @default(\"[]\")\n\n  connectedAt DateTime?\n  lastSyncAt  DateTime?\n  revokedAt   DateTime?\n\n  @@unique([userId, provider])\n  @@index([userId])\n}\n\n/// One import run. Rows are written even when parsing fails, so a member can\n/// see that their file was received and why it did not work.\nmodel HealthImport {\n  id     String @id @default(cuid())\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  provider String\n  // file | api\n  kind     String  @default(\"file\")\n  filename String?\n  // pending | complete | failed\n  status   String  @default(\"pending\")\n\n  metricCount Int     @default(0)\n  scanCount   Int     @default(0)\n  error       String?\n\n  createdAt  DateTime  @default(now())\n  finishedAt DateTime?\n\n  @@index([userId, createdAt])\n}\n\n/// A day of normalised metrics from one source. Imports from several apps can\n/// coexist for the same day, and the app picks a winner at read time rather\n/// than destroying the others on write.\nmodel HealthMetric {\n  id     String @id @default(cuid())\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  /// Midnight UTC of the day being described.\n  date   DateTime\n  source String\n\n  restingHr       Int?\n  /// Mean heart rate across the whole day, which is a different animal from\n  /// the resting figure: it moves with training load, caffeine and stress.\n  averageHr       Int?\n  hrvMs           Float?\n  sleepMinutes    Int?\n  steps           Int?\n  activeKcal      Int?\n  weightKg        Float?\n  respiratoryRate Float?\n  spo2            Float?\n\n  createdAt DateTime @default(now())\n\n  @@unique([userId, date, source])\n  @@index([userId, date])\n}\n\n/// A post in the feed. One model covers the three things someone can put out —\n/// a note, a progress shot, or a livestream — because they share an author, a\n/// body and a place in the timeline, and splitting them would mean three\n/// queries to build one feed.\nmodel Post {\n  id       String @id @default(cuid())\n  authorId String\n  author   User   @relation(fields: [authorId], references: [id], onDelete: Cascade)\n\n  /// note | progress | live\n  kind String @default(\"note\")\n  body String\n\n  /// Progress shots and livestream thumbnails. Remote URL or a data URI.\n  mediaUrl  String?\n  /// live | ended — null for everything that was never a livestream.\n  liveState String?\n\n  /// public | members — members-only posts are the paid tier.\n  visibility String @default(\"public\")\n\n  /// Denormalised so the feed does not count rows per post on every read.\n  likeCount    Int @default(0)\n  commentCount Int @default(0)\n\n  likes    PostLike[]\n  comments Comment[]\n\n  createdAt DateTime @default(now())\n\n  @@index([createdAt])\n  @@index([authorId, createdAt])\n}\n\nmodel PostLike {\n  postId String\n  post   Post   @relation(fields: [postId], references: [id], onDelete: Cascade)\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n\n  @@id([postId, userId])\n}\n\nmodel Follow {\n  followerId String\n  follower   User   @relation(\"follower\", fields: [followerId], references: [id], onDelete: Cascade)\n  followeeId String\n  followee   User   @relation(\"followee\", fields: [followeeId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n\n  @@id([followerId, followeeId])\n}\n\n/// A paired V1. Kept as its own row rather than a flag on the profile so the\n/// pairing history survives someone swapping bands, and so the app can show\n/// battery and firmware without inventing them.\nmodel BandDevice {\n  id     String @id @default(cuid())\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  /// Printed inside the strap loop. Unique across every band we ship.\n  serial    String @unique\n  colourway String @default(\"ember\")\n  firmware  String @default(\"1.0.0\")\n\n  batteryPercent Int       @default(100)\n  pairedAt       DateTime  @default(now())\n  lastSyncAt     DateTime?\n\n  @@index([userId])\n}\n\nmodel Notification {\n  id     String @id @default(cuid())\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  /// like | follow | live | band | order | system\n  kind  String\n  title String\n  body  String\n\n  readAt    DateTime?\n  createdAt DateTime  @default(now())\n\n  @@index([userId, createdAt])\n}\n\n/// Someone working through a Map. The Map itself is content, not user data, so\n/// it lives in src/lib/maps/catalog.ts — only the progress belongs here.\nmodel MapEnrollment {\n  id     String @id @default(cuid())\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  mapId String\n  /// 1-based, so \"week 4\" in the UI is 4 here.\n  week  Int    @default(1)\n  /// Sessions finished in the current week.\n  done  Int    @default(0)\n\n  startedAt   DateTime  @default(now())\n  completedAt DateTime?\n\n  @@unique([userId, mapId])\n}\n\n/// A direct-message thread. Members are a many-to-many rather than two columns\n/// so group threads work later without a migration that rewrites history.\nmodel Conversation {\n  id      String @id @default(cuid())\n  members User[] @relation(\"members\")\n\n  messages Message[]\n\n  createdAt     DateTime @default(now())\n  lastMessageAt DateTime @default(now())\n\n  @@index([lastMessageAt])\n}\n\nmodel Message {\n  id             String       @id @default(cuid())\n  conversationId String\n  conversation   Conversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)\n\n  senderId String\n  sender   User   @relation(\"sender\", fields: [senderId], references: [id], onDelete: Cascade)\n\n  body   String\n  readAt DateTime?\n\n  createdAt DateTime @default(now())\n\n  @@index([conversationId, createdAt])\n}\n\nmodel Comment {\n  id     String @id @default(cuid())\n  postId String\n  post   Post   @relation(fields: [postId], references: [id], onDelete: Cascade)\n\n  authorId String\n  author   User   @relation(fields: [authorId], references: [id], onDelete: Cascade)\n\n  body String\n\n  createdAt DateTime @default(now())\n\n  @@index([postId, createdAt])\n}\n\n/// An Expo push token for one install. Tokens rotate and the same person can\n/// have several devices, so this is keyed by token rather than by user.\nmodel PushDevice {\n  id     String @id @default(cuid())\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  token    String @unique\n  platform String @default(\"ios\")\n\n  createdAt  DateTime @default(now())\n  lastSeenAt DateTime @default(now())\n\n  @@index([userId])\n}\n\n/// A session someone actually did. Sets are stored as JSON because their shape\n/// belongs to the exercise, not the schema, and nothing queries inside them —\n/// the row is read back whole to show what you lifted last time.\nmodel SessionLog {\n  id     String @id @default(cuid())\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  mapId     String\n  sessionId String\n  /// Which week of the Map this was, so \"last time\" compares like with like.\n  week      Int\n\n  /// [{ exercise, sets: [{ reps, weightKg, done }] }]\n  entries String @default(\"[]\")\n\n  durationSeconds Int?\n  notes           String?\n\n  completedAt DateTime @default(now())\n\n  @@index([userId, mapId, completedAt])\n  @@index([userId, sessionId])\n}\n\n/// Every administrative action, appended and never updated.\n///\n/// Staff can read other people's health data and change their orders, so the\n/// record of who did what is not optional — and it is written in the same\n/// transaction as the change so an action cannot exist without its entry.\nmodel AuditLog {\n  id      String @id @default(cuid())\n  actorId String\n  actor   User   @relation(fields: [actorId], references: [id], onDelete: Cascade)\n\n  /// order.refund | user.plan | user.admin | post.remove | broadcast.send\n  action String\n  /// What was acted on, so the entry is meaningful without the payload.\n  target String\n  /// JSON: whatever the action needs to be reconstructed.\n  detail String @default(\"{}\")\n\n  createdAt DateTime @default(now())\n\n  @@index([createdAt])\n  @@index([actorId, createdAt])\n}\n"
}

